# -*- coding: utf-8 -*-
"""Module for configuration base classes.

:author: Bartłomiej Idzikowski, Juergen Richter
:contact: bartlomiej.idzikowski@nsn.com, juergen.richter@nsn.com
"""
import pprint


class Config(object):
    """Base class for all configurations.

    All configuration objects have to inherit from Config to have special config access syntax and behavior.

    .. code-block:: python

        class Pdu(Config):
            SUPPORTED_DEVICES = ["APC", "SWH"]

            def __init__(self, host, outlet, device_type="APC"):
                validator = And(IsNotEmpty(), IsIpAddress())
                self._set_attr("host", host, validator)

                validator = IsNumber()
                self._set_attr("outlet", outlet, validator)

                validator = And(IsString(), IsOneOf(Pdu.SUPPORTED_DEVICES))
                self._set_attr("device_type", device_type, validator)

        pdu = Pdu(host="1.1.1.1", outlet=1)
    """
    def __init__(self, *args, **kwargs):
        self._attributes = {}

    def dump(self, path=None):
        """Method for dumping errors from config.

        :param list path: Name of package where all configurations are stored.

        :return: Message which contains keys and validation results of Config object.
        :rtype: string
        """
        path = ['config'] if path is None else path
        dump_message = ""
        for key, value in iter(self._attributes.items()):
            if isinstance(value, Config):
                dump_message = "{}{}".format(dump_message, value.dump(path + [str(key)]))
            elif all([self._hasattr(value, x) for x in ['value', 'result', 'message']]):
                dump_message = ("{}\n\n".format(dump_message) +
                                "#{}\n".format("="*62) +
                                "#{}\n".format('.'.join(path + [str(key)])) +
                                "#{}\n".format("="*62) +
                                value.message)
        return dump_message

    def is_valid(self):
        """Method is checking that configuration is valid.

        :return: Validation result of the Config.
        :rtype: boolean
        """
        for value in iter(self._attributes.values()):
            if all([self._hasattr(value, x) for x in ['value', 'result', 'message']]):
                return False
            elif isinstance(value, Config):
                if not value.is_valid():
                    return False
        return True

    def _set_attr(self, name, value, validator=None):
        """Method for setting config attributes and validating them.

        :param string name: Attribute name.
        :param value: Attribute value.
        :param Validator validator: Validator using to validate attribute value.

        .. code-block:: python

           # with attribute validation
           port_validator = And(IsNumber(), ValidPortRange())
           self._set_attr("port", port, port_validator)

           # without attribute validation
           self._set_attr("server", server)
        """
        if self._hasattr(validator, 'validate'):
            validation_result = validator.validate(value)
            value = value if validation_result.result else validation_result
        self._attributes[name] = value

    def __getattr__(self, item):
        return self._attributes[item]

    def __getitem__(self, item):
        return self if item == 1 else self._attributes[item]

    def __tree__(self):
        result = {}
        for key, value in iter(self._attributes.items()):
            if isinstance(value, Config):
                result[key] = value.__tree__()
            elif key.startswith('_'):
                continue
            else:
                result[key] = str(value)
        return result

    def __str__(self):
        return pprint.pformat(self.__tree__())

    def __iter__(self):
        return iter(self.__tree__().items())

    def _hasattr(self, value, attr):
        try:
            return hasattr(value, attr)
        except:
            return False

    def __setstate__(self, state):
        self.__dict__ = state

    def __getstate__(self):
        return self.__dict__
